#if APP_TESTS
using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Windows;using System.Windows.Controls;
namespace FileCompass {
 internal static class ProgramUxAuditTests {
  internal static int Run(string root){Directory.CreateDirectory(root);var log=new List<string>();MainWindow main=null;ConfigurationDialog settings=null;Window sample=null;try{Action<bool,string> check=delegate(bool ok,string text){if(!ok)throw new Exception(text);log.Add(text);};L.ChangeLanguage("cs");main=new MainWindow(root,new ProgramSettings{AutoRefresh=false}){Left=-18000,Top=-18000,WindowStartupLocation=WindowStartupLocation.Manual,ShowActivated=false};main.Show();NavigationTests.WaitPanels(main);settings=new ConfigurationDialog(main);settings.Left=-18000;settings.Show();settings.Sections.SelectedItem=L.Text("settings.archivesSection");FluentUiTests.Children<SettingsPager>(settings).Single().Select("Externí");NavigationTests.Wait(System.Threading.Tasks.Task.Delay(100));var inputs=FluentUiTests.Children<TextBox>(settings).Where(x=>x.IsVisible).ToArray();check(inputs.Length==3,"all three external archiver paths are visible");foreach(var input in inputs){input.Text=@"C:\Program Files\Archive Tool\archiver.exe";input.UpdateLayout();var host=input.Template.FindName("PART_ContentHost",input) as ScrollViewer;check(host!=null&&host.ActualHeight>=input.FontSize*1.1&&host.ViewportHeight+1>=host.ExtentHeight,"archiver path text host has enough height");}NextStageTests.Draw(settings,Path.Combine(root,"archivers.png"));settings.Sections.SelectedItem=L.Text("settings.panelsSection");NavigationTests.Wait(System.Threading.Tasks.Task.Delay(100));check(FluentUiTests.Children<TextBlock>(settings).Where(x=>x.IsVisible&&x.FontSize<18&&x.FontFamily.Source!="Segoe MDL2 Assets").All(x=>x.FontSize==14),"normal panel-setting text uses one font size");settings.Sections.SelectedItem=L.Text("updates.title");NavigationTests.Wait(System.Threading.Tasks.Task.Delay(160));settings.UpdateLayout();var update=settings.UpdatePage;check(FluentUiTests.Children<Button>(update).Any(x=>Convert.ToString(x.Content)==L.Text("updates.download")&&x.IsVisible),"download action is visible on the component list page");check(FluentUiTests.Children<Button>(update).Any(x=>Convert.ToString(x.Content)==L.Text("updates.apply")&&x.IsVisible),"activate action stays on the same page");check(update.Items.Items.Count>=7,"all update components remain in one list");foreach(var item in update.Items.Items){var row=update.Items.ItemContainerGenerator.ContainerFromItem(item) as DataGridRow;check(row!=null&&row.TranslatePoint(new Point(0,row.ActualHeight),update.Items).Y<=update.Items.ActualHeight+1,"update component row is fully visible");}NextStageTests.Draw(settings,Path.Combine(root,"updates.png"));settings.Close();settings=null;
    main.ToggleFluentDrawer();NavigationTests.Wait(System.Threading.Tasks.Task.Delay(100));main.UpdateLayout();var drawer=FluentUiTests.Children<Border>(main).Single(x=>Convert.ToString(x.Tag)=="fluent-drawer");var cascade=FluentUiTests.Children<Menu>(drawer).Single(x=>Convert.ToString(x.Tag)=="cascade-menu");var groups=cascade.Items.OfType<MenuItem>().ToArray();check(groups.Length>=11,"all categories are in the vertical cascade menu");for(int i=1;i<groups.Length;i++)check(groups[i].TranslatePoint(new Point(),drawer).Y>groups[i-1].TranslatePoint(new Point(),drawer).Y,"menu categories are ordered vertically");groups[0].IsSubmenuOpen=true;NavigationTests.Wait(System.Threading.Tasks.Task.Delay(100));NextStageTests.Draw(main,Path.Combine(root,"drawer.png"));
    bool clicked=false;var original=new MenuItem{Header="Test menu"};var leaf=new MenuItem{Header="Checked action",IsCheckable=true};leaf.Click+=delegate{clicked=true;};original.Items.Add(leaf);var rendered=DrawerControls.Group(original,delegate{});sample=new Window{Width=320,Height=220,Left=-18000,Top=-18000,Content=new Border{Tag="fluent-drawer",Child=rendered}};sample.Show();rendered.IsExpanded=true;NavigationTests.Wait(System.Threading.Tasks.Task.Delay(50));FluentUiTests.Children<Button>(rendered).Single().RaiseEvent(new RoutedEventArgs(Button.ClickEvent));check(clicked&&leaf.IsChecked,"drawer dispatch preserves original click handler and checked state");sample.Close();sample=null;main.Close();main=null;File.WriteAllLines(Path.Combine(root,"result.txt"),log.Concat(new[]{"PASS: "+log.Count}));return 0;
   }catch(Exception ex){File.WriteAllText(Path.Combine(root,"result.txt"),String.Join("\n",log)+"\nFAIL: "+ex);return 1;}finally{if(sample!=null)sample.Close();if(settings!=null)settings.Close();if(main!=null)main.Close();}}
 }
}
#endif
